def strange_sort_list(lst):
    if not lst:
        return []

    result = []
    odd = []
    even = []

    for i, num in enumerate(lst):
        if i % 2 == 0:
            even.append(num)
        else:
            odd.append(num)

    odd.sort(reverse=True)
    even.sort()

    while odd or even:
        if even:
            result.append(even.pop(0))
        if odd:
            result.append(odd.pop(0))

    return result

