def will_it_fly(q, w):
    # Check if the list is balanced (palindromic)
    if q != q[::-1]:
        return False

    # Calculate the sum of elements in the list
    total_weight = sum(q)

    # Check if the sum is less than or equal to the maximum possible weight
    if total_weight <= w:
        return True
    else:
        return False

