def smallest_change(arr):
    # Create a frequency dictionary to store the count of each number
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Count the frequency of numbers that appear an odd number of times
    odd_count = sum(val % 2 for val in freq.values())

    # The minimum number of changes needed is the count of numbers with odd frequency
    return max(0, odd_count - 1)

