def max_fill(grid, capacity):
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    wells = [[0 for _ in range(cols)] for _ in range(rows)]
    visits = [[0 for _ in range(cols)] for _ in range(rows)]

    def get_amount_from_well(x, y, current_bucket):
        if 0 <= x < rows and 0 <= y < cols and (not visits[x][y]):
            if grid[x][y]:
                amount_to_get = min(capacity - current_bucket, grid[x][y])
                if grid[x][y] == amount_to_get:
                    visits[x][y] = 1
                    wells[x][y] = True
                return amount_to_get
            else:
                wells[x][y] = True
            return 0
        else:
            return 0

    lower_bucket_times = 0

    for i in range(rows):
        for j in range(cols):
            lower_bucket_times += 1
            current_bucket = 0
            while(current_bucket != capacity):
                amount_to_fill = get_amount_from_well(i, j, current_bucket)
                current_bucket += amount_to_fill

    return lower_bucket_times

