def get_closest_vowel(word):
    vowels = 'AEIOUaeiou'
    for i in range(1, len(word)):
        if word[i - 1] not in vowels and word[i] not in vowels:
            if word[i + 1] in vowels:
                return word[i + 1]
            elif i + 2 != len(word) and word[i + 2] in vowels:
                return word[i + 2]
            elif i - 2 >= 0 and word[i - 2] in vowels:
                return word[i - 2]
    return ""

