def match_parens(lst):
    open_brackets = 0
    close_brackets = 0

    # check the first string
    for bracket in lst[0]:
        if bracket == '(':
            open_brackets += 1
        elif bracket == ')':
            close_brackets += 1

    # check if the difference is at most 1
    if abs(open_brackets - close_brackets) > 1:
        return 'No'

    # check the second string
    for bracket in lst[1]:
        if bracket == '(':
            open_brackets += 1
        elif bracket == ')':
            close_brackets += 1

    # check if the total difference is even
    if abs(open_brackets - close_brackets) % 2 == 1:
        return 'No'

    return 'Yes'

