def match_parens(lst):
    s = ''.join(lst)
    opening_count = s.count('(')
    closing_count = s.count(')')

    if opening_count < closing_count:
        return 'No'
    elif opening_count > closing_count:
        return 'Yes' if s.count('()') == s.count('(') - s.count(')') else 'No'
    else:
        return 'Yes'

