def get_odd_collatz(n):
    # Initialize the list with the starting number
    collatz = [n]
    while n not in [1, 2]:
        # If the number is even, divide it by 2
        if n % 2 == 0:
            n = n // 2
            collatz.append(n)
        # If the number is odd, multiply it by 3 and add 1
        else:
            n = 3 * n + 1
            collatz.append(n)
    # Return a sorted list of odd numbers in the collatz sequence
    # remove 2 since we don't want it in the sequence
    collatz.remove(2)   
    return sorted([num for num in collatz if num % 2 != 0] )

