def valid_date(date):
    try:
        # Split the date string by '-' and remove the empty strings
        day, month, year = [x for x in date.split('-') if x]

        # Check if the day, month and year are digits
        if not (day.isdigit() and month.isdigit() and year.isdigit()):
            return False

        # Convert the day, month and year to integers
        day, month, year = int(day), int(month), int(year)

        # Check if the month, day and year are in the correct range
        if not (1 <= month <= 12):
            return False
        if month in [1, 3, 5, 7, 8, 10, 12]:
            if not (1 <= day <= 31):
                return False
        elif month in [4, 6, 9, 11]:
            if not (1 <= day <= 30):
                return False
        elif month == 2:
            if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
                if not (1 <= day <= 29):
                    return False
            else:
                if not (1 <= day <= 28):
                    return False
        else:
            return False

        # If all checks pass, the date is valid
        return True

    except ValueError:
        # If a ValueError is raised, the date is invalid
        return False

