def is_sorted(lst):
    if len(lst) == 1:
        return True

    sorted_lst = []
    count_dict = {}
    for num in lst:
        if num not in count_dict:
            count_dict[num] = 1
        else:
            count_dict[num] += 1
        sorted_lst.append((num, count_dict[num]))

    sorted_lst = sorted(sorted_lst)

    return lst == [x[0] for x in sorted_lst]

