def largest_smallest_integers(lst):
    # Separate negative and positive integers
    negatives = [i for i in lst if i < 0]
    positives = [i for i in lst if i > 0]

    # Find the largest of negative integers and the smallest of positive integers
    if negatives:
        largest_negative = max(negatives)
    else:
        largest_negative = None

    if positives:
        smallest_positive = min(positives)
    else:
        smallest_positive = None

    return (largest_negative, smallest_positive)

