def largest_smallest_integers(lst):
    # Filter the list for negative and positive integers
    negative_integers = [i for i in lst if i < 0]
    positive_integers = [i for i in lst if i > 0]

    # If there are no negative or positive integers, return None
    if not negative_integers and not positive_integers:
        return None, None

    # If there are no negative integers, find the smallest positive integer
