def file_name_check(file_name):
    # Check if the file's name contains exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file's name into two substrings at the dot
    name, extension = file_name.split('.')

    # Check if the substring before the dot starts with a latin alphabet letter
    if not (name[0].isalpha()):
        return 'No'

    # Check if the substring after the dot is valid
    if extension not in ['txt', 'exe', 'dll']:
        return 'No'

    # Check if there are more than three digits in the file's name
    if sum(char.isdigit() for char in file_name) > 3:
        return 'No'

    return 'Yes'

