def file_name_check(file_name):
    # Check if the file's name contains exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file's name into two substrings at the dot
    name, extension = file_name.split('.')

    # Check if the substring before the dot starts with a latin alphapet letter
    if not re.match('^[a-zA-Z]', name):
        return 'No'

    # Check if the substring before the dot is empty
    if not name:
        return 'No'

    # Check if there are more than three digits in the file's name
    if len(re.findall('\d', file_name)) > 3:
        return 'No'

    # Check if the substring after the dot is one of the allowed extensions
    if extension not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

