def eat(number, need, remaining):
    total_eaten = number + need
    if total_eaten > remaining:
        return [remaining, 0]
    else:
        return [total_eaten, remaining - total_eaten]

print(eat(5, 6, 10))  # -> [11, 4]
print(eat(4, 8, 9))   # -> [12, 1]
print(eat(1, 10, 10)) # -> [11, 0]
print(eat(2, 11, 5))  # -> [7, 0]

def do_algebra(operator, operand):
    stack = []
    operator_set = {
        "+": lambda x, y: x + y,
        "-": lambda x, y: x - y,
        "*": lambda x, y: x * y,
        "/": lambda x, y: x // y,
        "**": lambda x, y: x ** y
    }

    for i in range(len(operator)):
        if i == 0:
            stack.append(operand[i])
        elif i == len(operator) - 1:
            result = stack.pop()
            for _ in range(i):
                operand1 = stack.pop()
                op = operator.pop()
                result = operator_set[op](operand1, result)
            stack.append(result)
        else:
            operand2 = operand[i]
            op = operator.pop()
            stack.append(stack.pop() + (operator_set[op](stack.pop(), operand2) if op in ['+', '-', '*'] else (stack.pop() ** operand2)))

    return stack.pop()

# Example
print(do_algebra(["+", "*"], [2, 3]))  # Output: 5

